import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import UniversalSearchBar from './components/UniversalSearchBar';
import TempleCardGrid from './components/TempleCardGrid';
import NearbyStaysGrid from './components/NearbyStaysGrid';
import ChatbotWidget from './components/ChatbotWidget';
import PaymentModal from './components/PaymentModal';
import AmenitiesGrid from './components/AmenitiesGrid';
import ScamRadar from './components/ScamRadar';
import CrowdMonitor from './components/CrowdMonitor';
import DarshanQueue from './components/DarshanQueue';
import StayReservation from './components/StayReservation';
import { LanguageProvider } from './i18n/translations';

export default function App() {
  const [crowd, setCrowd] = useState(null);
  const [darshan, setDarshan] = useState([]);
  const [amenities, setAmenities] = useState([]);
  const [rates, setRates] = useState([]);
  const [temples, setTemples] = useState([]);
  const [stays, setStays] = useState([]);
  const [lastPing, setLastPing] = useState("");
  const [searchTerm, setSearchTerm] = useState("");

  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [paymentItem, setPaymentItem] = useState(null);
  const [paymentType, setPaymentType] = useState('token'); // 'token' or 'stay'

  const fetchData = async () => {
    try {
      const [crowdRes, darshanRes, amenitiesRes, ratesRes, templesRes, staysRes] = await Promise.all([
        fetch('http://localhost:8000/api/crowd/feed').then(r => r.json()),
        fetch('http://localhost:8000/api/darshan/timings').then(r => r.json()),
        fetch('http://localhost:8000/api/amenities/list').then(r => r.json()),
        fetch('http://localhost:8000/api/scam-radar/rates').then(r => r.json()),
        fetch('http://localhost:8000/api/temples').then(r => r.json()),
        fetch('http://localhost:8000/api/stays/hotels').then(r => r.json())
      ]);
      setCrowd(crowdRes);
      setDarshan(Array.isArray(darshanRes) ? darshanRes : []);
      setAmenities(Array.isArray(amenitiesRes) ? amenitiesRes : []);
      setRates(Array.isArray(ratesRes) ? ratesRes : []);
      setTemples(Array.isArray(templesRes) ? templesRes : []);
      setStays(Array.isArray(staysRes) ? staysRes : []);
      setLastPing(new Date().toLocaleTimeString());
    } catch (err) {
      console.error("Fetch failure:", err);
    }
  };

  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 4000); // Polls every 4s for live updates
    return () => clearInterval(interval);
  }, []);

  const openPayment = (item, type) => {
    setPaymentItem(item);
    setPaymentType(type);
    setPaymentModalOpen(true);
  };

  return (
    <LanguageProvider>
      <div style={{ 
        background: 'linear-gradient(135deg, #f8fafc 0%, #e2e8f0 100%)', 
        minHeight: '100vh', 
        padding: '24px 16px', 
        fontFamily: 'Inter, sans-serif' 
      }}>
        <div style={{ maxWidth: '1200px', margin: '0 auto' }}>

          <Navbar lastPing={lastPing} />

          <UniversalSearchBar searchTerm={searchTerm} setSearchTerm={setSearchTerm} />

          <TempleCardGrid temples={temples} searchTerm={searchTerm} onGetToken={(temple) => openPayment(temple, 'token')} />

          <NearbyStaysGrid stays={stays} searchTerm={searchTerm} onBookStay={(stay) => openPayment(stay, 'stay')} />

          <CrowdMonitor crowd={crowd} />

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '24px', marginBottom: '24px' }}>
            <DarshanQueue darshan={darshan} />
            {/* <StayReservation hotels={stays} /> */}
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '24px' }}>
            <AmenitiesGrid amenities={amenities} />
            <ScamRadar rates={rates} />
          </div>

          <ChatbotWidget />

          <PaymentModal 
            isOpen={paymentModalOpen} 
            onClose={() => setPaymentModalOpen(false)} 
            item={paymentItem} 
            type={paymentType} 
          />
        </div>
      </div>
    </LanguageProvider>
  );
}
